#!/usr/bin/env python3
"""Render the static catalogue from reviewed JSON records; never recalculate science."""
from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parents[1]
studies=json.loads((ROOT/'data/studies.json').read_text())['studies']
integrations=json.loads((ROOT/'data/integrations.json').read_text())['integrations']
def bi(ja,en,tag='span',attrs=''):
 return f'<{tag} data-ja="{e(ja,quote=True)}" data-en="{e(en,quote=True)}" {attrs}>{e(ja)}</{tag}>'
def link(path,ja,en,cls=''):
 return f'<a href="{e(path,quote=True)}" class="{cls}" data-preserve-language>{bi(ja,en)}</a>'
def page(path,title,body,depth=0,active='papers'):
 pre='../'*depth
 nav=f'<nav class="nav" aria-label="Library">'+''.join(f'<a href="{pre}{p}" '+('aria-current="page"' if active==k else '')+f' data-preserve-language>{bi(j,en)}</a>' for k,p,j,en in [('papers','index.html','論文別','Studies'),('integrations','integrations/','統合解析','Integrations')])+'</nav>'
 html=f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'none'; object-src 'none'; base-uri 'none'"><title>{e(title)} · Ovary Macrophage Library</title><link rel="stylesheet" href="{pre}assets/library.css"></head><body><a class="skip" href="#main">本文へ / Skip to content</a><div class="shell"><header class="top"><a class="brand" href="{pre}index.html" data-preserve-language>Ovary / Macrophages</a><label class="lang"><span>Language / 言語</span><select id="language" aria-label="Language / 言語"><option value="ja">日本語</option><option value="en">English</option></select></label></header>{nav}<main id="main">{body}</main><footer class="foot"><span>{bi('計算済み結果のライブラリ · 更新 2026-10-31','Saved analysis library · Updated 2026-10-31')}</span><a href="{pre}data/studies.json">{bi('収録データ一覧','Catalogue data')}</a></footer></div><script src="{pre}assets/library.js"></script></body></html>'''
 target=ROOT/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html+'\n')
rows=[]
for s in studies:
 rows.append(f'''<article class="entry"><h3>{e(s['short_name'])}</h3><p class="paper-title">{e(s['title'])}</p><div class="facts"><span>{e(s['species'])}</span><span>{bi(f"候補 {s['n_cells']:,}細胞",f"{s['n_cells']:,} candidate cells")}</span><span>{bi(f"{s['n_genes']:,}遺伝子",f"{s['n_genes']:,} genes")}</span></div><p class="small muted">{bi(s['annotation']['ja'],s['annotation']['en'])}</p><div class="actions">{link(s['page']+'viewer/?run='+s['default_run'],'候補集団を見る','Explore candidates','primary')}{link(s['page'],'論文と解析の詳細','Study details')}</div></article>''')
body=f'''<header class="intro">{bi('卵巣マクロファージ・ライブラリ','Ovary macrophage library','h1')}{bi('論文ごとの解析結果を、いつでも見返すための場所。クラスターを選び、気になる遺伝子の発現を確認できます。','A home for revisiting analysis results by study. Choose a cluster and explore gene expression.','p','class="lede"')}</header><div class="catalogue"><section>{bi('論文別の解析','Analyses by study','h2')}<p class="small muted">{bi(f'{len(studies)}論文を収録 · 閲覧専用',f'{len(studies)} study available · Read-only')}</p>{''.join(rows)}</section><aside class="note">{bi('このライブラリについて','About this library','h2')}{bi('UMAP・クラスターは事前に計算した結果です。Web上では結果を選んで表示し、新しい再解析は実行しません。','UMAPs and clusters are computed in advance. The website displays saved results; it does not run new analyses.','p')}{bi('「マクロファージ候補」は検討中の注釈です。元論文・抽出条件・解析履歴を併せて確認してください。','“Macrophage candidates” is a working annotation. Check the original study, selection criteria and analysis history.','p')}{link('integrations/','統合解析のページへ','View integrations')}</aside></div>'''
page('index.html','Library',body)
for s in studies:
 default=s['default_run'];whole=s['whole_run'];analyses=s['analyses'];default_record=next(a for a in analyses if a['id']==default);whole_record=next(a for a in analyses if a['id']==whole);qc_children=[a for a in analyses if a['parent']==default];other=[a for a in analyses if a['id']!=default and a['parent']!=default]
 def listing(items):
  return '<ul class="analysis-list">'+''.join(f'''<li><div><strong>{bi(a['name']['ja'],a['name']['en'])}</strong><span class="counts">{bi(f"{a['n_cells']:,}細胞 · {a['n_clusters']}群",f"{a['n_cells']:,} cells · {a['n_clusters']} clusters")} · {bi('既存UMAP' if a['kind']=='imported_existing_analysis' else '部分集団の再解析','Imported UMAP' if a['kind']=='imported_existing_analysis' else 'Subset reanalysis')}</span></div>{link('viewer/?run='+a['id'],'開く','Open')}</li>''' for a in items)+'</ul>'
 meta=[('生物種','Species',s['species'],s['species']),('マクロファージ候補','Candidate subset',f"{s['n_cells']:,}細胞 / QC後 / {default_record['n_clusters']}群",f"{s['n_cells']:,} cells / post-QC / {default_record['n_clusters']} groups"),('卵巣全体','Whole ovary',f"{s['whole_ovary_n_cells']:,}細胞 / {whole_record['n_clusters']}群",f"{s['whole_ovary_n_cells']:,} cells / {whole_record['n_clusters']} clusters"),('遺伝子','Genes',f"{s['n_genes']:,}（収録全遺伝子）",f"{s['n_genes']:,} (all included genes)"),('保存版','Snapshot',s['snapshot_date']+' · v'+s['version'],s['snapshot_date']+' · v'+s['version'])]
 body=f'''<div class="breadcrumb">{link('../../index.html','ライブラリへ戻る','Back to library')}</div><header class="intro">{bi(s['page_title']['ja'],s['page_title']['en'],'h1')}<p>{e(s['title'])}<br><span class="muted">{e(s['journal'])}</span></p><div class="actions">{link('viewer/?run='+default,f"候補{s['n_cells']:,}細胞を開く",f"Explore {s['n_cells']:,} cells",'primary')}<a class="inline-link" href="{s['doi']}">{bi('原論文','Original paper')}</a><a class="inline-link" href="{s['source']}">{bi('公開元データ（OSF）','Source data (OSF)')}</a></div></header><p class="small muted">{bi(s['included_scope']['ja'],s['included_scope']['en'])}</p><section class="note">{bi('候補集団の位置づけ','How to interpret this subset','h2')}{bi(s['interpretation']['ja'],s['interpretation']['en'],'p')}</section><section>{bi('データと解析条件','Data and analysis context','h2')}<dl class="metadata">{''.join('<dt>'+bi(j,en)+'</dt><dd>'+bi(vj,ve)+'</dd>' for j,en,vj,ve in meta)}</dl>{bi(s['conditions']['ja'],s['conditions']['en'],'p')}{bi(s['methods']['ja'],s['methods']['en'],'p')}{bi('発現表示は保存カウントから ln(1 + count / 細胞の全遺伝子合計 × target sum) を描画時に求めます。UMAPやクラスタリングの再計算は行いません。解析条件・環境・元ファイルのハッシュはビューアーの「解析条件と出典」で確認できます。取り込んだ既存UMAPの設定欄にはアプリ側の保存値・既定値が含まれる可能性があり、原著の手順を厳密に再現した証明ではありません。','Expression display evaluates ln(1 + count / full-gene cell total × target sum) from saved counts when drawing. It does not recompute UMAP or clustering. Settings, environment and source hashes are available under “Analysis settings and provenance” in the viewer. Imported UMAP metadata may contain application defaults; it does not establish exact reproduction of the original paper’s methods.','p','class="small muted"')}</section><section>{bi('候補集団の保存済み解析','Saved candidate analyses','h2')}{listing([a for a in analyses if a['id']==default]+qc_children)}</section><section>{bi('卵巣全体・旧解析の参照','Whole-ovary context and legacy analyses','h2')}{bi('以下は参照用です。卵巣全体のクラスターを、すべてマクロファージと解釈しないでください。','These results provide context. Whole-ovary clusters must not all be interpreted as macrophages.','p','class="muted"')}{listing(other)}</section>'''
 page(s['page']+'index.html',s['short_name'],body,2)
protocol=[('対象と比較条件を決める','Define the comparison','生物種・性周期・年齢・処置など、比較する条件と採用する論文を指定します。','Specify studies, species and biological conditions such as cycle stage, age and treatment.'),('細胞と遺伝子をそろえる','Harmonize cells and features','各論文でQCと細胞種注釈を確認し、遺伝子IDを対応させます。論文・サンプル・個体・条件のIDを保持します。','Review QC and cell-type annotations in each study, harmonize feature IDs, and retain study, sample, donor and condition IDs.'),('統合と検証を計算環境で行う','Compute and validate integration','必要なバッチ補正を行い、補正前後の分布と生物学的差異の保持を確認します。論文と条件が重なる交絡は補正だけでは解消できません。','Apply justified batch correction and inspect both mixing and biological-signal preservation. Confounding between study and condition cannot be solved by correction alone.'),('結果を版として公開する','Publish a versioned result','UMAP・クラスター・発現行列・解析条件・入力のハッシュを保存します。統合前の発現値と補正後の表現を区別し、差次的発現では個体を反復単位として扱います。','Save UMAPs, clusters, expression matrices, parameters and input hashes. Distinguish uncorrected expression from corrected representations; use donors as biological replicates for differential expression.')]
body=f'''<header class="intro">{bi('論文を横断した統合解析','Cross-study integration','h1')}{bi('複数論文を組み合わせて計算した結果を、独立した保存版として残します。','Joint analyses across studies belong here as independent, versioned results.','p','class="lede"')}</header><section class="note"><span class="pill">{bi('公開済み結果 0件','0 published results')}</span>{bi('まだ統合結果はありません','No integrated results yet','h2')}{bi('現在収録している単一細胞研究はMorris 2022の1論文です。複数論文の統合計算はまだ行っていません。新しい結果が完成して検証されたら、この一覧に追加します。','The library currently includes one single-cell study, Morris 2022. No cross-study integration has been computed. Completed and validated results will be added to this catalogue.','p')}{link('../index.html','論文別の結果を見る','Browse study results')}</section><section>{bi('並べて比較することと、統合すること','Comparison is not integration','h2')}{bi('別々の論文のUMAPを並べても、座標やクラスター番号は直接対応しません。統合解析には細胞・遺伝子・条件の対応付けと、必要に応じたバッチ補正、検証が必要です。異なる生物種の統合ではオルソログの対応も明示します。','UMAP coordinates and cluster numbers from separate studies are not directly equivalent. Joint integration needs harmonized cells, features and conditions, justified batch correction, and validation. Cross-species work also requires explicit ortholog mapping.','p')}</section><section>{bi('統合結果を追加するまで','Before adding an integrated result','h2')}<ol class="protocol">{''.join('<li><strong>'+bi(j,en)+'</strong>'+bi(dj,de,'p')+'</li>' for j,en,dj,de in protocol)}</ol></section>'''
# An empty catalogue is deliberate. Adding records requires result pages and reviewed status.
if integrations:
 cards=[]
 for it in integrations:
  if it['status']=='available': cards.append('<li>'+link('../'+it['page'],it['title']['ja'],it['title']['en'])+'</li>')
 body='<header class="intro">'+bi('論文を横断した統合解析','Cross-study integration','h1')+'</header><ul>'+''.join(cards)+'</ul><section>'+body.split('<section>',1)[1]
page('integrations/index.html','Integrations',body,1,'integrations')
print('Rendered',len(studies)+2,'library pages')
